R Implementation

Libraries

library(deSolve)
library(tidyverse)



Why Integration Method Matters
This model is a critical illustration of why Euler integration fails for oscillating systems. Euler approximates each step using only the derivative at the start of the step. In an oscillating system, the derivative changes rapidly within each step, and Euler systematically overestimates the amplitude — producing oscillations that grow rather than sustain.
RK4 evaluates the derivative at four points within each step, tracking the curvature accurately and maintaining constant amplitude.

model &lt;- function(time, stocks, params) {
  with(as.list(c(stocks, params)), {
    c_gap               &lt;- p_desired_position - s_position
    f_changing_position &lt;- s_velocity
    f_changing_velocity &lt;- (p_gravity / p_length_of_pendulum) * c_gap
    ds_position_dt      &lt;- f_changing_position
    ds_velocity_dt      &lt;- f_changing_velocity
    return(list(
      c(ds_position_dt, ds_velocity_dt),
      gap          = c_gap,
      acceleration = f_changing_velocity
    ))
  })
}

stocks &lt;- c(s_position = 0.15, s_velocity = 0)
params &lt;- c(p_desired_position = 0, p_gravity = 9.8, p_length_of_pendulum = 1)

comparison_times &lt;- seq(0, 10, 0.25)

sim_euler &lt;- ode(
  times = comparison_times, y = stocks, parms = params,
  func = model, method = "euler"
) |&gt;
  as_tibble() |&gt;
  mutate(time = as.numeric(time), s_position = as.numeric(s_position)) |&gt;
  select(time, s_position) |&gt;
  mutate(method = "Euler (step = 0.25 s)")

sim_rk4 &lt;- ode(
  times = comparison_times, y = stocks, parms = params,
  func = model, method = "rk4"
) |&gt;
  as_tibble() |&gt;
  mutate(time = as.numeric(time), s_position = as.numeric(s_position)) |&gt;
  select(time, s_position) |&gt;
  mutate(method = "RK4 (step = 0.25 s)")

bind_rows(sim_euler, sim_rk4) |&gt;
  ggplot(aes(x = time, y = s_position, colour = method)) +
  geom_line(linewidth = 0.8) +
  scale_colour_manual(
    values = c("Euler (step = 0.25 s)" = "#d45b4e",
               "RK4 (step = 0.25 s)"  = "#4e8cd4")
  ) +
  labs(x = "Time (seconds)", y = "Position (metres)", colour = NULL) +
  theme_minimal(base_size = 12) +
  theme(legend.position = "bottom")







Figure 3: Euler integration produces artificially expanding oscillations — a numerical artefact, not a property of the model. RK4 correctly produces sustained oscillations at constant amplitude. Both runs use the same step size (0.25 s) and the same model.





All further runs use method = "rk4".


Model Function
The model follows the standard deSolve function signature. Variable names use the project’s prefix convention (s_ stocks, p_ parameters, c_ converters, f_ flows).

model &lt;- function(time, stocks, params) {
  with(as.list(c(stocks, params)), {
    c_gap               &lt;- p_desired_position - s_position
    f_changing_position &lt;- s_velocity
    f_changing_velocity &lt;- (p_gravity / p_length_of_pendulum) * c_gap
    ds_position_dt      &lt;- f_changing_position
    ds_velocity_dt      &lt;- f_changing_velocity
    return(list(
      c(ds_position_dt, ds_velocity_dt),
      gap          = c_gap,
      acceleration = f_changing_velocity
    ))
  })
}

stocks &lt;- c(s_position = 0.15, s_velocity = 0)
params &lt;- c(p_desired_position = 0, p_gravity = 9.8, p_length_of_pendulum = 1)

The pendulum is released from a displacement of 0.15 metres with zero initial velocity. Desired Position is zero (the equilibrium resting point). Pendulum length is 1 metre.


Solving and Visualising

sim_time &lt;- seq(0, 10, 0.01)

sim_data &lt;- ode(
  times = sim_time,
  y     = stocks,
  parms = params,
  func  = model,
  method = "rk4"
) |&gt;
  as_tibble() |&gt;
  mutate(across(everything(), as.numeric))


sim_data |&gt;
  select(time, s_position, s_velocity) |&gt;
  pivot_longer(-time, names_to = "variable", values_to = "value") |&gt;
  mutate(
    variable = recode(variable,
                      "s_position" = "Position (metres)",
                      "s_velocity" = "Velocity (m/s)")
  ) |&gt;
  ggplot(aes(x = time, y = value)) +
  geom_line(colour = "#4e8cd4", linewidth = 0.8) +
  facet_wrap(~variable, ncol = 1, scales = "free_y") +
  labs(x = "Time (seconds)", y = NULL) +
  theme_minimal(base_size = 12)







Figure 4: Position and velocity of the pendulum over 10 seconds. Both oscillate at constant amplitude, 90 degrees out of phase — when position is at its maximum, velocity is zero (the momentary pause before reversal), and when velocity is at its peak, position is at zero (the bob passing through equilibrium at full speed).





The 90-degree phase offset between position and velocity is a signature of sustained oscillation and is visible in the phase portrait — a plot of velocity against position.

sim_data |&gt;
  ggplot(aes(x = s_position, y = s_velocity)) +
  geom_path(colour = "#4e8cd4", linewidth = 0.7) +
  geom_point(data = sim_data[1, ], aes(x = s_position, y = s_velocity),
             colour = "#d45b4e", size = 2.5) +
  annotate("text", x = 0.155, y = 0.03, label = "start",
           size = 3, colour = "#d45b4e", hjust = 0) +
  labs(x = "Position (metres)", y = "Velocity (m/s)") +
  theme_minimal(base_size = 12)







Figure 5: Phase portrait of the pendulum. For a frictionless (undamped) pendulum, the trajectory is a closed ellipse — the system returns to exactly the same state each cycle. The direction of travel is clockwise: from the starting point (position = 0.15, velocity = 0) the bob accelerates leftward (velocity becomes negative), reaches zero position at maximum negative velocity, decelerates, and returns.

Model function
The model follows the standard deSolve function signature. Variable names use the project’s prefix convention (s_ stocks, p_ parameters, c_ converters, f_ flows).

model &lt;- function(time, stocks, params) {
  with(as.list(c(stocks, params)), {

    c_prob_contact_sick &lt;- s_sick / (s_healthy + s_sick)

    f_catching_illness &lt;- s_healthy * c_prob_contact_sick *
                          p_population_interactions * p_prob_catching   # people/month
    f_recovering    &lt;- s_sick / p_duration_of_illness                # people/month

    ds_healthy_dt &lt;- f_recovering - f_catching_illness
    ds_sick_dt    &lt;- f_catching_illness - f_recovering

    return(list(c(ds_healthy_dt, ds_sick_dt),
                catching_illness = f_catching_illness,
                recovery_rate    = f_recovering))
  })
}

A Minimal Logistic SD Model
We implement the derivative expression directly as a deSolve model function.

logistic_model &lt;- function(time, stocks, params) {
  with(as.list(c(stocks, params)), {
    f_net &lt;- p_r * (s_burnt_out - p_L) * (1 - (s_burnt_out - p_L) / (p_K - p_L))
    list(c(f_net))
  })
}

sim_logistic &lt;- ode(
  y      = c(s_burnt_out = 11),
  times  = seq(1, 24, by = 0.1),
  parms  = c(p_K = p_K, p_L = p_L, p_r = p_r),
  func   = logistic_model,
  method = "rk4"
) |&gt;
  as_tibble() |&gt;
  mutate(
    time        = as.numeric(time),
    s_burnt_out = as.numeric(s_burnt_out),
    date        = as.Date("2023-01-01") + (time - 1) * 30.44
  )

The model function body is a direct translation of the derivative expression. with(as.list(c(stocks, params)), {...}) is the standard deSolve idiom that makes stock and parameter names available directly inside the braces. method = "rk4" is appropriate here because the logistic derivative changes rapidly near the inflection point, and RK4 evaluates at four sub-steps per interval to track that curvature accurately.
Let’s check that the ODE reproduces the curve from Part 1.








Figure 1: SD model output (blue) against observed data (grey). Parameters are seeded directly from the Part 1 nls fit. The close agreement confirms that the ODE correctly implements the derivative of the fitted logistic. The pipeline is closed: nls fitted the solution; the ODE specifies the derivative; the solver integrates it back to the same curve.

Separating the Flows
The single net flow f_net conflates two distinct processes. Expanding the logistic derivative algebraically separates them:
\[\frac{dy}{dt} = \underbrace{r \cdot (y - L)}_{\text{f\_in: contagion (R1)}} \ - \ \underbrace{\frac{r \cdot (y - L)^2}{K - L}}_{\text{f\_out: recovery drag (B1)}}\]
The inflow scales linearly with active burnout — each affected person increases pressure on the remaining team, accelerating further burnout. This is the reinforcing loop (R1). The outflow scales with the square of active burnout — as the affected count rises, density-dependent recovery effects strengthen and the balancing loop (B1) increasingly resists further growth. The two flows are in balance exactly at equilibrium: \(y^* = K\).

logistic_decomposed &lt;- function(time, stocks, params) {
  with(as.list(c(stocks, params)), {
    f_in  &lt;- p_r * (s_burnt_out - p_L)
    f_out &lt;- p_r * (s_burnt_out - p_L)^2 / (p_K - p_L)
    list(c(f_in - f_out), inflow = f_in, outflow = f_out)
  })
}

sim_decomposed &lt;- ode(
  y      = c(s_burnt_out = 11),
  times  = seq(1, 24, by = 0.1),
  parms  = c(p_K = p_K, p_L = p_L, p_r = p_r),
  func   = logistic_decomposed,
  method = "rk4"
) |&gt;
  as_tibble() |&gt;
  mutate(
    time        = as.numeric(time),
    s_burnt_out = as.numeric(s_burnt_out),
    date        = as.Date("2023-01-01") + (time - 1) * 30.44
  )

The trajectory is identical to the previous section — only the structure is now visible. Tracking inflow and outflow as separate outputs makes it possible to inspect when each loop dominates and when they equalise.








Figure 2: Stock-and-flow structure of the decomposed logistic. R1 (blue, reinforcing) closes through the stock back to the burning-out inflow; B1 (red, balancing) closes through the stock back to the recovering outflow. Both p_r and p_L appear in both flows — they set the shared rate and baseline. p_K appears only in the outflow: it is the capacity ceiling that makes B1 grow faster than R1 as the stock rises, eventually halting growth.

Policy Levers & Scenarios
We test four combinations of the two levers, holding the spread rate constant.

scenarios &lt;- list(
  `Current policy`  = c(p_spread_rate = 0.30, p_recovery_months = 7.3, p_intervention_threshold = 32),
  `Earlier trigger` = c(p_spread_rate = 0.30, p_recovery_months = 7.3, p_intervention_threshold = 20),
  `Recovery support` = c(p_spread_rate = 0.30, p_recovery_months = 4.0, p_intervention_threshold = 32),
  `Both levers`     = c(p_spread_rate = 0.30, p_recovery_months = 4.0, p_intervention_threshold = 20)
)

sim_results &lt;- imap_dfr(scenarios, function(params, label) {
  ode(y      = c(s_burnt_out = 11),
      times  = seq(1, 24, by = 0.1),
      func   = model_burnout,
      parms  = params,
      method = "rk4") |&gt;
    as_tibble() |&gt;
    transmute(
      scenario        = label,
      time            = as.numeric(time),
      date            = as.Date("2023-01-01") + (time - 1) * 30.44,
      burnt_out_staff = as.numeric(s_burnt_out)
    )
}) |&gt;
  mutate(scenario = factor(scenario, levels = names(scenarios)))

sim_results |&gt;
  group_by(scenario) |&gt;
  filter(time == max(time)) |&gt;
  transmute(scenario, equilibrium = round(burnt_out_staff, 1)) |&gt;
  print()

